<script setup lang="ts">
import { onMounted, ref } from 'vue'
type Schedule={id:number;patient_id:number;full_name:string;phone?:string;treatment_place_id:number;treatment_place:string;control_date:string;start_time:string;purpose:string|null;notes:string|null;status:'scheduled'|'missed'|'rescheduled'|'attended'}
type Place={id:number;name:string}
type PatientPreview={id:number;full_name:string;medical_record_number?:string;nik:string;phone:string;birth_date?:string;gender?:string;rt?:string;rw?:string;full_address?:string;photo_path?:string|null;status:string;cadre?:{full_name:string}}
const base=import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1',headers={Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'}
const items=ref<Schedule[]>([]),loading=ref(true),error=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),updating=ref<number|null>(null),selectedPatient=ref<PatientPreview|null>(null),previewLoading=ref(false),previewError=ref('')
const places=ref<Place[]>([]),editing=ref<Schedule|null>(null),saving=ref(false),deleting=ref<number|null>(null),actionError=ref(''),form=ref({treatment_place_id:'',control_date:'',start_time:'',purpose:'',notes:''})
const statuses:Record<Schedule['status'],string>={scheduled:'Terjadwal',missed:'Tidak Datang',rescheduled:'Ganti Tanggal',attended:'Datang Kontrol'}
const whatsapp=(phone?:string)=>phone?`https://wa.me/${phone.replace(/\D/g,'')}`:''
const formatDate=(value?:string)=>{if(!value)return '—';const [y,m,d]=value.slice(0,10).split('-');return y&&m&&d?`${d}/${m}/${y}`:value}
const photo=(patient:PatientPreview)=>patient.photo_path?`/media/profile/${patient.photo_path}`:'/icons/icon-512.png'
async function load(target=1){loading.value=true;error.value='';try{const r=await fetch(`${base}/control-schedules?page=${target}`,{headers}),p=await r.json();if(!r.ok)throw new Error(p.message||'Gagal memuat jadwal.');items.value=p.data;page.value=p.meta.current_page;lastPage.value=p.meta.last_page;total.value=p.meta.total}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat jadwal.'}finally{loading.value=false}}
async function updateStatus(item:Schedule){updating.value=item.id;try{const r=await fetch(`${base}/control-schedules/${item.id}/status`,{method:'PATCH',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({status:item.status})}),p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal memperbarui status jadwal.')}catch(e){error.value=e instanceof Error?e.message:'Gagal memperbarui status jadwal.';await load(page.value)}finally{updating.value=null}}
async function preview(item:Schedule){selectedPatient.value=null;previewLoading.value=true;previewError.value='';try{const r=await fetch(`${base}/patients/${item.patient_id}`,{headers}),p=await r.json();if(!r.ok)throw new Error(p.message??'Gagal memuat detail pasien.');selectedPatient.value=p.data}catch(e){previewError.value=e instanceof Error?e.message:'Gagal memuat detail pasien.'}finally{previewLoading.value=false}}
function closePreview(){selectedPatient.value=null;previewError.value=''}
async function edit(item:Schedule){editing.value=item;places.value=[];actionError.value='';form.value={treatment_place_id:String(item.treatment_place_id),control_date:item.control_date.slice(0,10),start_time:item.start_time.slice(0,5),purpose:item.purpose??'',notes:item.notes??''};try{const response=await fetch(`${base}/treatment-places`,{headers});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Gagal memuat tempat pengobatan.');places.value=payload.data; if(!places.value.some(place=>place.id===item.treatment_place_id))places.value.unshift({id:item.treatment_place_id,name:item.treatment_place})}catch(e){actionError.value=e instanceof Error?e.message:'Gagal memuat tempat pengobatan.'}}
async function saveEdit(){if(!editing.value||saving.value||!places.value.length)return;saving.value=true;actionError.value='';try{const response=await fetch(`${base}/control-schedules/${editing.value.id}`,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({...form.value,treatment_place_id:Number(form.value.treatment_place_id)})});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Gagal memperbarui jadwal.');editing.value=null;await load(page.value)}catch(e){actionError.value=e instanceof Error?e.message:'Gagal memperbarui jadwal.'}finally{saving.value=false}}
async function remove(item:Schedule){if(deleting.value!==null||!confirm(`Hapus jadwal kontrol ${item.full_name} tanggal ${formatDate(item.control_date)}?`))return;deleting.value=item.id;actionError.value='';try{const response=await fetch(`${base}/control-schedules/${item.id}`,{method:'DELETE',headers});if(!response.ok){const payload=await response.json();throw new Error(payload.message||'Gagal menghapus jadwal.')}await load(items.value.length===1&&page.value>1?page.value-1:page.value)}catch(e){actionError.value=e instanceof Error?e.message:'Gagal menghapus jadwal.'}finally{deleting.value=null}}
onMounted(()=>load())
</script>
<template><main class="admin-page"><section class="admin-content"><header class="schedule-heading"><div><p>Monitoring pasien</p><h1>Jadwal Kontrol</h1><p>Daftar jadwal kontrol pasien dan tempat pelayanan.</p></div><a class="add-button" href="/admin/schedules/create">+ Tambah Jadwal Pasien</a></header><p v-if="actionError && !editing" class="error" role="alert">{{actionError}}</p><section class="panel"><p v-if="loading">Memuat jadwal pasien…</p><div v-else-if="error"><p class="error">{{error}}</p><button @click="load(page)">Coba lagi</button></div><template v-else><p class="table-caption">{{total}} jadwal tercatat • Tanggal terbaru ditampilkan lebih dahulu</p><div class="schedule-table"><table><thead><tr><th>Pasien</th><th>No. HP</th><th>Tanggal kontrol</th><th>Jam Datang</th><th>Tempat pengobatan</th><th>Tujuan</th><th>Status kontrol</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><button class="patient-link" type="button" @click="preview(item)">{{item.full_name}}<small>Lihat profil pasien</small></button></td><td>{{item.phone||'—'}}<a v-if="whatsapp(item.phone)" class="whatsapp-button" :href="whatsapp(item.phone)" target="_blank" rel="noopener">WhatsApp</a></td><td>{{formatDate(item.control_date)}}</td><td>{{item.start_time.slice(0,5)}}</td><td>{{item.treatment_place}}</td><td>{{item.purpose||'—'}}</td><td><select v-model="item.status" class="status-select" :disabled="updating===item.id" @change="updateStatus(item)"><option v-for="(label,value) in statuses" :key="value" :value="value">{{label}}</option></select><small v-if="updating===item.id">Menyimpan…</small></td><td><div class="schedule-actions-cell"><button type="button" class="schedule-edit" @click="edit(item)">Edit</button><button type="button" class="schedule-delete" :disabled="deleting===item.id" @click="remove(item)">{{deleting===item.id?'Menghapus…':'Hapus'}}</button></div></td></tr><tr v-if="!items.length"><td colspan="8" class="empty-schedules">Belum ada jadwal kontrol.</td></tr></tbody></table></div><nav v-if="lastPage>1" class="schedule-pages"><button :disabled="page<=1" @click="load(page-1)">Sebelumnya</button><span>Halaman {{page}} dari {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Berikutnya</button></nav></template></section></section><div v-if="editing" class="preview-backdrop" @click.self="editing=null"><section class="schedule-edit-modal" role="dialog" aria-modal="true" aria-labelledby="schedule-edit-title"><button class="preview-close" type="button" aria-label="Tutup" @click="editing=null">×</button><h2 id="schedule-edit-title">Edit jadwal kontrol</h2><p>{{editing.full_name}}</p><form @submit.prevent="saveEdit"><label>Tempat pengobatan<select v-model="form.treatment_place_id" :disabled="!!actionError" required><option v-for="place in places" :key="place.id" :value="String(place.id)">{{place.name}}</option></select></label><label>Tanggal kontrol<input v-model="form.control_date" type="date" required></label><label>Jam datang<input v-model="form.start_time" type="time" required></label><label>Tujuan kontrol<input v-model="form.purpose" maxlength="255"></label><label>Catatan petugas<textarea v-model="form.notes" maxlength="2000"/></label><p v-if="actionError" class="error" role="alert">{{actionError}}</p><div class="schedule-edit-actions"><button type="button" class="schedule-cancel" @click="editing=null">Batal</button><button type="submit" class="schedule-edit" :disabled="saving || !!actionError || !places.length">{{saving?'Menyimpan…':'Simpan perubahan'}}</button></div></form></section></div><div v-if="previewLoading||selectedPatient||previewError" class="preview-backdrop" @click.self="closePreview"><section class="patient-preview-modal"><button class="preview-close" type="button" @click="closePreview">×</button><p v-if="previewLoading">Memuat profil pasien…</p><p v-else-if="previewError" class="error">{{previewError}}</p><template v-else-if="selectedPatient"><div class="preview-hero"><img :src="photo(selectedPatient)" alt="Foto pasien"><div><small>Profil pasien</small><h2>{{selectedPatient.full_name}}</h2><span>{{selectedPatient.status}}</span></div><a :href="whatsapp(selectedPatient.phone)" target="_blank" rel="noopener">WhatsApp</a><a class="view-history" :href="`/admin/patients/${selectedPatient.id}/history`">Lihat riwayat</a></div><dl class="preview-grid"><div><dt>No. Rekam Medis</dt><dd>{{selectedPatient.medical_record_number||'Belum tersedia'}}</dd></div><div><dt>NIK</dt><dd>{{selectedPatient.nik}}</dd></div><div><dt>Tanggal lahir</dt><dd>{{formatDate(selectedPatient.birth_date)}}</dd></div><div><dt>Jenis kelamin</dt><dd>{{selectedPatient.gender==='L'?'Laki-laki':'Perempuan'}}</dd></div><div><dt>Nomor HP</dt><dd>{{selectedPatient.phone}}</dd></div><div><dt>Kader PMO</dt><dd>{{selectedPatient.cadre?.full_name||'Belum ditetapkan'}}</dd></div><div class="wide"><dt>Alamat</dt><dd>{{selectedPatient.full_address||'Belum tersedia'}} · RT {{selectedPatient.rt||'—'}} / RW {{selectedPatient.rw||'—'}}</dd></div></dl></template></section></div></main></template>
<style scoped>
.schedule-actions-cell{display:flex;gap:7px;white-space:nowrap}.schedule-edit,.schedule-delete,.schedule-cancel{padding:8px 11px;border-radius:8px;border:1px solid #b9ddd5;background:#eef9f5;color:#087e72;font:600 12px Arial;cursor:pointer}.schedule-delete{border-color:#edc4bc;background:#fff3f0;color:#aa493b}.schedule-edit:disabled,.schedule-delete:disabled{opacity:.55;cursor:default}.schedule-edit-modal{position:relative;width:min(640px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:28px;box-shadow:0 25px 70px #102d3c55}.schedule-edit-modal h2{margin:0;color:#173f59}.schedule-edit-modal>p{color:#718b92}.schedule-edit-modal form{display:grid;grid-template-columns:1fr 1fr;gap:16px}.schedule-edit-modal label{font-size:13px;font-weight:600}.schedule-edit-modal label:first-child,.schedule-edit-modal label:nth-child(5){grid-column:1/-1}.schedule-edit-modal input,.schedule-edit-modal select,.schedule-edit-modal textarea{display:block;width:100%;min-width:0;margin-top:6px;padding:10px;border:1px solid #cddfdf;border-radius:8px;font:14px Arial}.schedule-edit-modal textarea{min-height:80px}.schedule-edit-actions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:8px}@media(max-width:600px){.schedule-edit-modal form{grid-template-columns:1fr}.schedule-edit-modal label:first-child,.schedule-edit-modal label:nth-child(5){grid-column:auto}}.schedule-heading{gap:16px;flex-wrap:wrap}.table-caption{color:#66858c;font-size:12px}.schedule-table{overflow-x:auto}.schedule-table table{min-width:980px}.patient-link{border:0;background:none;padding:0;text-align:left;color:#183f59;font:700 13px Arial;cursor:pointer}.patient-link:hover{color:#078b7d;text-decoration:underline}.patient-link small{display:block;margin-top:4px;color:#0b9385;font-size:10px;font-weight:400}.whatsapp-button{display:block;width:max-content;margin-top:5px;padding:5px 9px;border-radius:7px;background:#dff7e9;color:#128a4e;text-decoration:none;font-size:10px;font-weight:bold}.status-select{min-width:145px;padding:8px 10px;border:1px solid #b9ddd5;border-radius:8px;background:#f2fbf8;color:#087e72;font:600 12px Arial;cursor:pointer}.schedule-table small{display:block;margin-top:4px;color:#718b92;font-size:10px}.empty-schedules{text-align:center;padding:40px 16px!important;color:#718b89}.schedule-pages{display:flex;align-items:center;justify-content:flex-end;gap:14px;margin-top:20px;font-size:12px}.preview-backdrop{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:20px;background:#153d4175;backdrop-filter:blur(3px)}.patient-preview-modal{position:relative;width:min(680px,100%);max-height:90vh;overflow:auto;border-radius:20px;background:#fff;box-shadow:0 25px 70px #102d3c55}.preview-close{position:absolute;right:15px;top:14px;z-index:1;width:34px;height:34px;border:0;border-radius:50%;background:#edf7f5;color:#087e72;font-size:22px;cursor:pointer}.patient-preview-modal>p{padding:30px}.preview-hero{display:flex;align-items:center;gap:14px;padding:28px;background:linear-gradient(120deg,#e2fbf7,#edfaff)}.preview-hero img{width:76px;height:76px;border:3px solid #fff;border-radius:20px;object-fit:cover}.preview-hero small{color:#0b8b7e;font-size:11px;font-weight:700;text-transform:uppercase}.preview-hero h2{margin:5px 0;color:#173f59;font-size:23px}.preview-hero span{border-radius:999px;padding:4px 8px;background:#dff7e9;color:#10854a;font-size:10px;font-weight:700}.preview-hero a{border-radius:9px;padding:9px 12px;background:#d9f8e7;color:#0f864b;font-size:12px;font-weight:700;text-decoration:none}.preview-hero .view-history{background:#0b9385;color:#fff}.preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:22px;margin:0}.preview-grid div{padding:12px;border-radius:11px;background:#f6fbfa}.preview-grid .wide{grid-column:1/-1}.preview-grid dt{font-size:10px;font-weight:700;color:#6e8991;text-transform:uppercase}.preview-grid dd{margin:5px 0 0;color:#294e60;font-size:13px;overflow-wrap:anywhere}@media(max-width:650px){.preview-hero{flex-wrap:wrap;padding:22px 16px}.preview-hero img{width:58px;height:58px}.preview-hero h2{font-size:18px}.preview-grid{grid-template-columns:1fr;padding:16px}.preview-grid .wide{grid-column:auto}}
</style>
